CREATE TABLE IF NOT EXISTS resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, workspace_id uuid NOT NULL, name text NOT NULL, resource_type text NOT NULL, readiness text NOT NULL CHECK (readiness IN ('ready','not_ready','unknown')), location text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS response_queue_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, workspace_id uuid NOT NULL, title text NOT NULL, priority text NOT NULL, destination text, notes text, status text NOT NULL DEFAULT 'queued', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS response_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, workspace_id uuid NOT NULL, queue_item_id uuid NOT NULL REFERENCES response_queue_items(id), resource_id uuid NOT NULL REFERENCES resources(id), status text NOT NULL CHECK (status IN ('assigned','acknowledged','en_route','completed')), approved_by uuid NOT NULL, approved_at timestamptz NOT NULL, updated_at timestamptz, UNIQUE (workspace_id, resource_id, status));
